def _asset_web_url(path: Path) -> str:
    """Return a Dash-served /assets URL, including safe encoding for spaces."""
    try:
        relative = path.resolve().relative_to(ASSETS_ROOT.resolve()).as_posix()
    except ValueError:
        return ""
    return "/assets/" + urllib.parse.quote(relative, safe="/")


def _team_photo_files() -> list[Path]:
    """Return supported team portraits in a stable order."""
    if not TEAM_PHOTOS_DIR.is_dir():
        return []
    return sorted(
        (path for path in TEAM_PHOTOS_DIR.iterdir()
         if path.is_file() and path.stat().st_size > 256
         and path.suffix.lower() in {".png", ".jpg", ".jpeg", ".webp"}),
        key=lambda path: path.name.lower(),
    )


def _team_photo_path(member_name: str, member_index: int | None = None) -> Path | None:
    """Resolve a member portrait by name, then by stable folder order."""
    photos = _team_photo_files()
    if not photos:
        return None

    slug = "".join(
        ch.lower() if ch.isalnum() else "_"
        for ch in member_name
    ).strip("_")
    slug = "_".join(part for part in slug.split("_") if part)

    candidates = (
        f"{slug}.png",
        f"{slug}.jpg",
        f"{slug}.jpeg",
        f"{slug}.webp",
        f"{slug.replace('_', '-')}.png",
        f"{slug.replace('_', '-')}.jpg",
        f"{slug.replace('_', '-')}.webp",
    )
    for candidate in candidates:
        path = TEAM_PHOTOS_DIR / candidate
        if path.is_file() and path.stat().st_size > 256:
            return path

    # Small robustness layer for files that use a shortened stem.
    stem_tokens = set(slug.split("_"))
    for path in photos:
        normalized = path.stem.lower().replace("-", "_")
        if stem_tokens and stem_tokens.issubset(set(normalized.split("_"))):
            return path

    # If the supplied portraits use generic names such as 01.jpg, 02.jpg, ...
    # pair them deterministically with TEAM_MEMBERS order.
    if member_index is not None and 0 <= member_index < len(photos):
        return photos[member_index]
    return None


