@lru_cache(maxsize=1)
def corpus_stats() -> dict[str, int]:
    """Return lightweight corpus counts for the Overview screen."""
    if not CORPUS_PATH.is_file():
        return {"records": 0, "organizations": 0, "families": 0}
    rows, _ = read_csv_records(CORPUS_PATH)
    organizations = {row.get("organization", "") for row in rows if row.get("organization")}
    families: set[str] = set()
    for row in rows:
        description = (row.get("description") or "").strip()
        if description:
            families.add(extract_attributes(description).family)
    return {
        "records": len(rows),
        "organizations": len(organizations),
        "families": len(families),
    }


@lru_cache(maxsize=1)
def search_index() -> tuple[HybridSearchEngine, dict[str, MaterialRecord]]:
    """Build the existing Matrixen retrieval index exactly once per process."""
    if not CORPUS_PATH.is_file():
        raise FileNotFoundError(f"Material corpus is unavailable: {CORPUS_PATH}")

    rows, _ = read_csv_records(CORPUS_PATH)
    records: list[MaterialRecord] = []
    families: list[str] = []

    for row in rows:
        description = (row.get("description") or "").strip()
        if not description:
            continue

        family = extract_attributes(description).family
        material = MaterialRecord(
            source_system=row.get("source_system") or "unknown",
            source_organization=row.get("organization") or "",
            source_record_id=row.get("tender_id") or row.get("tender_reference") or "",
            source_url=row.get("source_url") or "",
            source_document=row.get("document_url") or "",
            source_section=row.get("source_section") or "",
            material_code=row.get("corpus_id") or "",
            raw_description=description,
            normalized_description=NORMALIZER.normalize(description).normalized_text,
            organization=row.get("organization") or "",
        )
        records.append(material)
        families.append(family)

    engine = HybridSearchEngine(
        records,
        document_ids=[record.id for record in records],
        families=families,
        embedding_service=EmbeddingService(),
    )
    return engine, {record.id: record for record in records}



def review_tasks() -> list[dict[str, str]]:
    """Read the persisted review queue without mutating it."""
    try:
        return [
            {
                "id": task.id,
                "material_a": task.pair.material_a,
                "material_b": task.pair.material_b,
                "status": task.status.value,
                "assigned_to": task.assigned_to or "Unassigned",
            }
            for task in ReviewQueue(DATABASE).list(limit=100)
        ]
    except Exception as exc:  # pragma: no cover - presentation fallback
        return [{
            "id": "QUEUE-UNAVAILABLE",
            "material_a": "—",
            "material_b": "—",
            "status": "Unavailable",
            "assigned_to": str(exc),
        }]


