@lru_cache(maxsize=1)
def _runtime_quality_report() -> dict[str, Any] | None:
    """Build a read-only quality profile from the committed corpus when the manifest is absent."""
    if not CORPUS_PATH.is_file():
        return None
    try:
        report, _, _ = DataQualityChecker().profile_csv(CORPUS_PATH)
        payload = report.as_dict()
        payload["runtime_generated"] = True
        return payload
    except Exception:
        return None


@lru_cache(maxsize=1)
def _demo_nmc_payload() -> dict[str, Any]:
    """Create a clearly labelled, deterministic demo NMC from a real corpus row."""
    if not CORPUS_PATH.is_file():
        return {}
    try:
        rows, _ = read_csv_records(CORPUS_PATH)
        for row in rows:
            description = (row.get("description") or "").strip()
            if not description:
                continue
            try:
                proposal = NMCGenerator().propose(description)
            except (TypeError, ValueError):
                continue
            return {
                "nmc": proposal.nmc,
                "family": proposal.family,
                "status": proposal.status,
                "approval_status": proposal.approval_status,
                "attribute_signature": proposal.attribute_signature,
                "canonical_description": proposal.canonical_description,
                "source_description": description,
                "demo_only": True,
            }
    except Exception:
        pass
    return {}



_LIVE_LOCK = Lock()
_LAST_CORPUS_SIGNATURE: tuple[int, int] | None = None
_LAST_QUALITY_SIGNATURE: tuple[int, int] | None = None
_WARMUP_THREAD_STARTED = False


def _file_signature(path: Path) -> tuple[int, int] | None:
    """Return a cheap change signature without reading a large dataset."""
    try:
        stat = path.stat()
        return int(stat.st_mtime_ns), int(stat.st_size)
    except OSError:
        return None


def _safe_api_health(timeout: float = 1.5) -> tuple[bool, str]:
    """Probe the configured local API without ever blocking the dashboard for long."""
    url = f"{API_BASE}/health"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:  # noqa: S310
            status = int(getattr(response, "status", 200))
            body = response.read(4096).decode("utf-8", errors="replace")
            if status < 400:
                try:
                    payload = json.loads(body) if body else {}
                    version = str(payload.get("version") or payload.get("app_version") or "healthy")
                except json.JSONDecodeError:
                    version = "healthy"
                return True, version
            return False, f"HTTP {status}"
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        return False, str(exc)[:100] or "unavailable"


def live_status_component(*, checked_at: str | None = None, force_refresh: bool = False) -> html.Div:
    """Small always-visible status surface showing source/API freshness at a glance."""
    global _LAST_CORPUS_SIGNATURE, _LAST_QUALITY_SIGNATURE
    corpus_sig = _file_signature(CORPUS_PATH)
    quality_sig = _file_signature(QUALITY_PATH)
    api_ok, api_detail = _safe_api_health() if force_refresh else (False, "pending")
    with _LIVE_LOCK:
        _LAST_CORPUS_SIGNATURE = corpus_sig
        _LAST_QUALITY_SIGNATURE = quality_sig
    corpus_text = "source ready" if corpus_sig else "source missing"
    quality_text = "quality profile" if quality_sig else "quality pending"
    api_text = f"API {api_detail}" if api_ok else "API local fallback"
    checked = checked_at or datetime.now(timezone.utc).astimezone().strftime("%H:%M:%S")
    tone = "live-ok" if api_ok and corpus_sig else "live-local"
    return html.Div([
        html.Span(className=f"live-status-dot {tone}", **{"aria-hidden": "true"}),
        html.Div([
            html.Div("LIVE DATA", className="live-status-label"),
            html.Div(f"{corpus_text} · {quality_text} · {api_text} · checked {checked}", className="live-status-copy"),
        ], className="live-status-copy-wrap"),
    ], className="live-status glass-card-soft", role="status", **{"aria-live": "polite"})


def operation_spinner(title: str, subtitle: str) -> html.Div:
    """Immediate, lightweight operation loader: mathematics + orbital motion + halftone."""
    dots = [html.Span(className="mx-op-dot") for _ in range(17)]
    formula = [
        html.Span("∑", className="mx-op-formula-glyph"),
        html.Span("π", className="mx-op-formula-glyph"),
        html.Span("∫", className="mx-op-formula-glyph"),
        html.Span("Δ", className="mx-op-formula-glyph"),
    ]
    return html.Div([
        html.Div([*dots], className="mx-op-halftone", **{"aria-hidden": "true"}),
        html.Div(formula, className="mx-op-formula", **{"aria-hidden": "true"}),
        html.Div([
            html.Div(className="mx-op-orbit mx-op-orbit-a"),
            html.Div(className="mx-op-orbit mx-op-orbit-b"),
            html.Div(className="mx-op-orbit mx-op-orbit-c"),
            html.Div(className="mx-op-core"),
            html.Span(className="mx-op-bokeh mx-op-bokeh-a"),
            html.Span(className="mx-op-bokeh mx-op-bokeh-b"),
            html.Span(className="mx-op-bokeh mx-op-bokeh-c"),
        ], className="mx-op-mark", **{"aria-hidden": "true"}),
        html.Div(title, className="mx-op-title"),
        html.Div(subtitle, className="mx-op-subtitle"),
        html.Div([html.Span(className="mx-op-progress-fill")], className="mx-op-progress-track", **{"aria-hidden": "true"}),
    ], className="mx-operation-spinner", role="status", **{"aria-live": "polite"})


def loading_surface(component: Any, title: str, subtitle: str, *, target_components: dict[str, Any] | None = None) -> dcc.Loading:
    """Wrap a result with the Matrixen callback-state loader."""
    kwargs: dict[str, Any] = {
        "type": "default",
        # Show immediately: long-running callbacks must never look frozen.
        "delay_show": 0,
        "delay_hide": 90,
        "fullscreen": False,
        "custom_spinner": operation_spinner(title, subtitle),
        "overlay_style": {
            "visibility": "visible",
            "backgroundColor": "rgba(247,251,249,.60)",
            "backdropFilter": "blur(1px)",
            "WebkitBackdropFilter": "blur(1px)",
        },
        "parent_className": "mx-loading-parent",
        "className": "mx-loading-container",
    }
    if target_components:
        kwargs["target_components"] = target_components
    return dcc.Loading(component, **kwargs)


def csv_payload(rows: list[dict[str, Any]], *, dataset_name: str, metadata: dict[str, Any], filename: str) -> dict[str, Any]:
    """Create a standards-friendly CSV payload with an explicit metadata section."""
    output = io.StringIO(newline="")
    writer = csv.writer(output)
    writer.writerow(["MATRIXEN MATERIAL INTELLIGENCE EXPORT"])
    writer.writerow(["Dataset", dataset_name])
    writer.writerow(["Exported at", datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")])
    for key, value in metadata.items():
        writer.writerow([str(key), "" if value is None else str(value)])
    writer.writerow([])
    if rows:
        fieldnames: list[str] = []
        for row in rows:
            for key in row.keys():
                if key not in fieldnames:
                    fieldnames.append(key)
        writer.writerow(fieldnames)
        for row in rows:
            writer.writerow([row.get(key, "") for key in fieldnames])
    else:
        writer.writerow(["No records returned"])
    return {"content": output.getvalue(), "filename": filename, "type": "text/csv", "base64": False}


def _quality_export_rows(report: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for section_key in ("error_counts", "warning_counts", "info_counts"):
        values = report.get(section_key) or {}
        for name, count in values.items():
            rows.append({"section": section_key, "issue_or_signal": name, "count": count})
    return rows


def _safe_count(value: Any) -> int:
    """Coerce report counts defensively; profiling manifests can serialize numbers differently."""
    try:
        return int(value)
    except (TypeError, ValueError):
        try:
            return int(float(value))
        except (TypeError, ValueError):
            return 0


def _demo_stage_snapshot(state: dict[str, Any]) -> html.Div:
    stages = [
        ("01", "Live fetch", "Read current source rows"),
        ("02", "Normalize", "Extract attributes + normalize"),
        ("03", "Hybrid search", "Rank evidence candidates"),
        ("04", "Model score", "Pair compatibility + rationale"),
        ("05", "Governance", "Review queue + registry context"),
        ("06", "Quality + export", "Profile + package evidence"),
    ]
    completed = set(state.get("completed", []))
    active = int(state.get("active_stage", 0))
    cards = []
    for idx, (num, title, copy) in enumerate(stages):
        if idx in completed:
            cls = "demo-stage demo-stage-done"
            marker = "✓"
        elif idx == active and state.get("active"):
            cls = "demo-stage demo-stage-live"
            marker = "…"
        else:
            cls = "demo-stage"
            marker = num
        cards.append(html.Div([
            html.Div(marker, className="demo-stage-marker"),
            html.Div(title, className="demo-stage-title"),
            html.Div(copy, className="demo-stage-copy"),
        ], className=cls))
    return html.Div(cards, className="demo-stage-grid")


def _demo_metrics(state: dict[str, Any]) -> html.Div:
    metrics = state.get("metrics") or {}
    values = [
        ("Source rows", metrics.get("source_rows", "—"), "live corpus"),
        ("Family", metrics.get("family", "—"), "extracted from source"),
        ("Candidates", metrics.get("candidate_count", "—"), "hybrid retrieval"),
        ("Pair score", metrics.get("pair_score", "—"), "existing model"),
        ("Review tasks", metrics.get("review_tasks", "—"), "persisted queue"),
        ("Quality signals", metrics.get("quality_signals", "—"), "profile counts"),
    ]
    return html.Div([
        html.Div([
            html.Div(label, className="demo-metric-label"),
            html.Div(str(value), className="demo-metric-value"),
            html.Div(detail, className="demo-metric-detail"),
        ], className="demo-metric")
        for label, value, detail in values
    ], className="demo-metric-grid")


