def text_badge(text: str, tone: str = "neutral") -> html.Span:
    return html.Span(text, className=f"badge badge-{tone}")


def stat_card(label: str, value: str, detail: str, tone: str = "teal") -> html.Div:
    return html.Div([
        html.Div(label.upper(), className="stat-label"),
        html.Div(value, className="stat-value"),
        html.Div(detail, className="stat-detail"),
        html.Span(className=f"stat-accent stat-accent-{tone}"),
    ], className="stat-card glass-card")


def page_section(kicker: str, title: str, body: list[Any], *, extra_class: str = "") -> html.Section:
    return html.Section([
        html.Div(kicker.upper(), className="section-kicker"),
        html.H2(title, className="section-title"),
        html.Div(body, className="section-body"),
    ], className=f"panel glass-card {extra_class}".strip())


def empty_state(title: str, message: str, symbol: str = "○") -> html.Div:
    return html.Div([
        html.Div(symbol, className="empty-symbol"),
        html.H3(title, className="empty-title"),
        html.P(message, className="empty-copy"),
    ], className="empty-state")


def error_state(title: str, message: str, detail: str | None = None) -> html.Div:
    """Render a safe, user-facing callback failure without exposing a traceback."""
    body = [
        html.Div("!", className="empty-symbol"),
        html.H3(title, className="empty-title"),
        html.P(message, className="empty-copy"),
    ]
    if detail:
        body.append(html.Div(detail, className="error-detail"))
    body.append(html.Div("Retry the action after checking the live-data indicator.", className="error-retry-hint"))
    return html.Div(body, className="empty-state error-state")


def info_tile(title: str, copy: str) -> html.Div:
    return html.Div([
        html.Div(title, className="info-tile-title"),
        html.Div(copy, className="info-tile-copy"),
    ], className="info-tile")


def table_from_rows(rows: list[list[Any]], headers: list[str], *, class_name: str = "data-table") -> html.Div:
    return html.Div(
        html.Table([
            html.Thead(html.Tr([html.Th(header) for header in headers])),
            html.Tbody([html.Tr([html.Td(cell) for cell in row]) for row in rows]),
        ], className=class_name),
        className="table-scroll",
    )


def code_block(value: str) -> html.Pre:
    return html.Pre(value, className="result-block code-surface")


