def abstract_line_art() -> html.Div:
    """Pure-DOM art layer: subtle, semantic, and intentionally non-interactive."""
    return html.Div([
        html.Span(className="line-art line-art-one"),
        html.Span(className="line-art line-art-two"),
        html.Span(className="line-art line-art-three"),
        html.Span(className="line-art line-art-four"),
    ], className="abstract-line-art", **{"aria-hidden": "true"})


def model_logo(size: str = "normal") -> html.Div:
    """Minimal Matrixen mark: an M-shaped evidence graph with a discovery lens."""
    dims = {"small": 40, "normal": 60, "large": 84}
    px = dims.get(size, dims["normal"])
    return html.Div([
        html.Span(className="mx-logo-grid"),
        html.Span(className="mx-logo-m mx-logo-m-a"),
        html.Span(className="mx-logo-m mx-logo-m-b"),
        html.Span(className="mx-logo-node mx-logo-node-a"),
        html.Span(className="mx-logo-node mx-logo-node-b"),
        html.Span(className="mx-logo-node mx-logo-node-c"),
        html.Span(className="mx-logo-lens"),
        html.Span(className="mx-logo-handle"),
    ], className=f"mx-model-logo mx-model-logo-{size}", role="img", **{
        "aria-label": "Matrixen unified material intelligence",
        "style": {"--mx-logo-size": f"{px}px"},
    })


