def workspace_tabs() -> html.Nav:
    """Explicit button navigation; avoids dcc.Tabs focus/scroll edge cases."""
    return html.Nav(
        [
            html.Button(
                label,
                id=f"nav-{value}",
                n_clicks=0,
                type="button",
                className="workspace-tab is-active" if value == "overview" else "workspace-tab",
            )
            for label, value in WORKSPACE_TABS
        ],
        id="workspace-tabs",
        className="workspace-tabs",
        **{"aria-label": "Main workspace navigation"},
    )


def quick_route(symbol: str, title: str, copy: str, tab_value: str) -> html.Button:
    return html.Button([
        html.Span(symbol, className="route-symbol"),
        html.Span(title, className="route-title"),
        html.Span(copy, className="route-copy"),
        html.Span("Open →", className="route-arrow"),
    ], id={"type": "quick-route", "tab": tab_value}, n_clicks=0, className="quick-route-card", type="button")


def trust_card(title: str, copy: str) -> html.Div:
    return html.Div([
        html.Div("●", className="trust-dot"),
        html.Div(title, className="trust-title"),
        html.P(copy, className="trust-copy"),
    ], className="trust-card")


