app = Dash(
    __name__,
    title="Matrixen | Material Intelligence",
    update_title="Matrixen · loading",
    suppress_callback_exceptions=True,
    serve_locally=True,
)
server = app.server
app.layout = build_layout


app.clientside_callback(
    """
    function(n) {
        var loader = document.getElementById('matrixen-loading-screen');
        var status = document.getElementById('boot-status-text');
        if (n === undefined || n === null) {
            return [false, 'Loading...', 'boot-status boot-status-loading'];
        }

        // This callback executes only after Dash has mounted the application and
        // its renderer can run a callback. That is the real boot-ready signal.
        if (loader) {
            loader.classList.add('is-ready');
            window.setTimeout(function () {
                if (loader && loader.parentNode) loader.parentNode.removeChild(loader);
            }, 520);
        }
        if (status) {
            status.setAttribute('aria-label', 'Website loaded successfully');
        }
        return [true, 'Ready', 'boot-status boot-status-ready'];
    }
    """,
    Output("boot-ready", "data"),
    Output("boot-status-text", "children"),
    Output("boot-status-text", "className"),
    Input("boot-ready-check", "n_intervals"),
    prevent_initial_call=False,
)


def create_app() -> Dash:
    """Return the configured Dash app for package/WSGI imports."""
    return app


SCREEN_FACTORIES = {
    "overview": overview_screen,
    "search": search_screen,
    "match": match_screen,
    "nmc": nmc_screen,
    "governance": governance_screen,
    "quality": quality_screen,
    "demo": demo_screen,
    "about": about_screen,
}

NAV_IDS = [f"nav-{value}" for _, value in WORKSPACE_TABS]
NAV_INPUTS = [Input(nav_id, "n_clicks") for nav_id in NAV_IDS]
NAV_OUTPUTS = [Output(nav_id, "className") for nav_id in NAV_IDS]


@app.callback(
    [Output("screen-content", "children"), *NAV_OUTPUTS, Output("about-nav-button", "className")],
    [*NAV_INPUTS, Input({"type": "quick-route", "tab": ALL}, "n_clicks"), Input("about-nav-button", "n_clicks")],
    prevent_initial_call=True,
)
def navigate_workspace(*_clicks):
    """Deterministic app-local navigation; no href, hash, redirect, or tab scroll."""
    trigger = ctx.triggered_id

    if isinstance(trigger, dict):
        target = str(trigger.get("tab") or "overview")
    elif trigger == "about-nav-button":
        target = "about"
    elif isinstance(trigger, str) and trigger.startswith("nav-"):
        target = trigger[4:]
    else:
        target = "overview"

    factory = SCREEN_FACTORIES.get(target, overview_screen)
    screen = factory()
    classes = [
        "workspace-tab is-active" if value == target else "workspace-tab"
        for _, value in WORKSPACE_TABS
    ]
    about_class = "ghost-button top-nav-button is-current" if target == "about" else "ghost-button top-nav-button"
    return [screen, *classes, about_class]


