@app.callback(
    Output("review-query", "value"),
    Output("review-candidate", "options"),
    Output("review-candidate", "value"),
    Output("match-right", "value"),
    Output("review-candidate-provenance", "children"),
    Output("review-export-data", "data"),
    Input("review-search-submit", "n_clicks"),
    Input("review-query", "n_submit"),
    Input("review-candidate", "value"),
    Input("review-search-clear", "n_clicks"),
    State("review-query", "value"),
    State("review-candidate", "options"),
    State("review-export-data", "data"),
    prevent_initial_call=True,
)
def manage_review_candidates(_clicks: int | None, _query_submit: int | None, candidate_id: str | None, _clear_clicks: int | None, query: str | None, current_options, current_export):
    trigger = ctx.triggered_id
    if trigger == "review-search-clear":
        return "", [], None, "", "", []
    if trigger == "review-candidate":
        if not candidate_id or candidate_id == "__error__":
            return query or "", current_options or [], candidate_id, "", "", current_export or []
        try:
            _, records = search_index()
            record = records.get(candidate_id)
            if record is None:
                return query or "", current_options or [], None, "", empty_state("Record unavailable", "The selected source record is not present in the current index."), current_export or []
            evidence = html.Div([
                html.Div("SOURCE PROVENANCE", className="provenance-kicker"),
                html.Div(record.organization or "Organization not recorded", className="provenance-title"),
                html.Div(record.source_system or "Source system not recorded", className="provenance-line"),
                html.Div(record.source_section or "Source section not recorded", className="provenance-line"),
                html.Div(record.source_url or record.source_document or "Source URL/document not recorded", className="provenance-line"),
                html.Code(record.id, className="provenance-id"),
            ], className="provenance-card-inner")
            return query or "", current_options or [], candidate_id, record.raw_description, evidence, current_export or []
        except Exception as exc:  # pragma: no cover - runtime safeguard
            return query or "", current_options or [], candidate_id, "", error_state("Candidate could not be loaded", "The selected source record could not be resolved.", f"{type(exc).__name__}: {str(exc)[:180]}"), current_export or []
    if not query or not query.strip():
        return query or "", [], None, "", "", []
    try:
        engine, records = search_index()
        hits = engine.search(query.strip(), limit=12)
        options: list[dict[str, str]] = []
        export_rows: list[dict[str, Any]] = []
        for hit in hits:
            record = records.get(str(hit["candidate_id"]))
            if record is None:
                continue
            options.append({"label": f"{record.organization}: {record.raw_description[:110]}", "value": record.id})
            export_rows.append({
                "rank": hit.get("rank", ""),
                "name": record.raw_description[:120],
                "description": record.raw_description,
                "organization": record.organization or "",
                "lexical_score": hit.get("lexical_score", ""),
                "evidence_id": record.id,
                "source_system": record.source_system or "",
                "source_section": record.source_section or "",
                "source_url": record.source_url or record.source_document or "",
            })
        return query.strip(), options, None, "", "", export_rows
    except Exception as exc:  # pragma: no cover - runtime safeguard
        return query or "", [], None, "", error_state("Candidate search could not be completed", "The retrieval layer returned an unexpected runtime error.", f"{type(exc).__name__}: {str(exc)[:180]}"), []


@app.callback(
    Output("search-query", "value"),
    Output("search-family", "value"),
    Output("search-results", "children"),
    Output("search-export-data", "data"),
    Input("search-submit", "n_clicks"),
    Input("search-query", "n_submit"),
    Input("search-family", "n_submit"),
    Input("search-clear", "n_clicks"),
    State("search-query", "value"),
    State("search-family", "value"),
    prevent_initial_call=True,
)
def search_records(_clicks: int | None, _query_submit: int | None, _family_submit: int | None, _clear_clicks: int | None, query: str | None, family: str | None):
    if ctx.triggered_id == "search-clear":
        return "", "", "", []
    if not query or not query.strip():
        return query or "", family or "", empty_state("Nothing to search yet", "Enter a material description, then run the source-corpus search."), []
    try:
        engine, records = search_index()
        hits = engine.search(query.strip(), limit=20, family=family.strip() if family else None)
        if not hits:
            return query.strip(), family.strip() if family else "", empty_state("No candidate records found", "Try a broader description or remove the optional family filter."), []
        rows: list[list[Any]] = []
        export_rows: list[dict[str, Any]] = []
        for hit in hits:
            record = records.get(str(hit["candidate_id"]))
            if record is None:
                continue
            score = f"{float(hit['lexical_score']):.3f}"
            rows.append([hit["rank"], record.raw_description, record.organization or "—", score, str(hit["candidate_id"])])
            export_rows.append({
                "rank": hit["rank"],
                "name": record.raw_description[:120],
                "description": record.raw_description,
                "organization": record.organization or "",
                "family": family.strip() if family else "",
                "lexical_score": score,
                "evidence_id": str(hit["candidate_id"]),
                "source_system": record.source_system or "",
                "source_section": record.source_section or "",
                "source_url": record.source_url or record.source_document or "",
            })
        return query.strip(), family.strip() if family else "", html.Div([
            html.Div(f"{len(rows)} candidate record(s)", className="result-count"),
            table_from_rows(rows, ["Rank", "Description", "Organization", "Lexical score", "Evidence ID"]),
        ], className="search-results-table"), export_rows
    except Exception as exc:  # pragma: no cover - runtime safeguard
        return query or "", family or "", error_state("Search could not be completed", "The retrieval layer returned an unexpected runtime error.", f"{type(exc).__name__}: {str(exc)[:180]}"), []


@app.callback(
    Output("match-result", "children"),
    Output("match-export-data", "data"),
    Input("match-submit", "n_clicks"),
    State("match-left", "value"),
    State("match-right", "value"),
    prevent_initial_call=True,
)
def compare_pair(_clicks: int, left: str | None, right: str | None):
    if not left or not left.strip() or not right or not right.strip():
        return empty_state("Two descriptions are required", "Provide Material A and Material B before comparing evidence."), []
    try:
        decision, features = PairScorer().score(left.strip(), right.strip())
    except Exception as exc:  # pragma: no cover - runtime safeguard
        return error_state("Comparison could not be completed", "The matching layer returned an unexpected runtime error.", f"{type(exc).__name__}: {str(exc)[:180]}"), []
    feature_values = {name: getattr(features, name) for name in features.__dataclass_fields__}
    payload = {
        "score": decision.score,
        "score_semantics": decision.confidence_band,
        "calibrated_probability": decision.calibrated_probability,
        "compatibility": decision.compatibility,
        "requires_human_review": decision.requires_human_review,
        "rationale": decision.rationale,
        "features": feature_values,
    }
    decision_tone = "green" if decision.compatibility else "gold"
    export_row = {
        "material_a": left.strip(),
        "material_b": right.strip(),
        "score": decision.score,
        "score_semantics": decision.confidence_band,
        "calibrated_probability": decision.calibrated_probability,
        "compatibility": decision.compatibility,
        "requires_human_review": decision.requires_human_review,
        "rationale": decision.rationale,
        **{f"feature_{name}": value for name, value in feature_values.items()},
    }
    result = html.Div([
        html.Div([
            html.Div("MATCH SIGNAL", className="decision-kicker"),
            html.Div(str(decision.score), className="decision-score"),
            text_badge(str(decision.confidence_band), "teal"),
            text_badge("HUMAN REVIEW" if decision.requires_human_review else "REVIEW OPTIONAL", decision_tone),
        ], className="decision-hero"),
        html.Div([html.Div("Compatibility", className="metric-label"), html.Div(str(decision.compatibility), className="metric-value")], className="metric-card"),
        html.Div([html.Div("Calibrated probability", className="metric-label"), html.Div(str(decision.calibrated_probability), className="metric-value")], className="metric-card"),
        html.Div([html.Div("Rationale", className="rationale-kicker"), html.P(decision.rationale, className="rationale-copy")], className="rationale-card"),
        code_block(json.dumps(payload, indent=2, default=str)),
    ], className="match-result-inner")
    return result, [export_row]


@app.callback(
    Output("nmc-query", "value"),
    Output("nmc-result", "children"),
    Output("nmc-export-data", "data"),
    Input("nmc-submit", "n_clicks"),
    Input("nmc-query", "n_submit"),
    Input("nmc-clear", "n_clicks"),
    Input("nmc-demo-use", "n_clicks"),
    State("nmc-query", "value"),
    prevent_initial_call=True,
)
def lookup_nmc(
    _clicks: int | None,
    _query_submit: int | None,
    _clear_clicks: int | None,
    _demo_clicks: int | None,
    nmc: str | None,
):
    if ctx.triggered_id == "nmc-clear":
        return "", "", []
    if ctx.triggered_id == "nmc-demo-use":
        demo = _demo_nmc_payload()
        if not demo:
            return "", empty_state("Demo NMC unavailable", "The committed corpus did not yield a structured demonstration proposal."), []
        return demo["nmc"], code_block(json.dumps(demo, indent=2, default=str)), [demo]
    if not nmc or not nmc.strip():
        return nmc or "", empty_state("Enter an NMC", "Type a persisted NMC identifier to inspect its current stored state."), []
    demo = _demo_nmc_payload()
    if demo and nmc.strip() == demo.get("nmc"):
        demo_view = {**demo, "registry_state": "DEMO_ONLY_NOT_PERSISTED"}
        return nmc.strip(), code_block(json.dumps(demo_view, indent=2, default=str)), [demo_view]
    try:
        DATABASE.initialize()
        with DATABASE.sessions() as session:
            row = session.get(NMCRegistryRow, nmc.strip())
            if row is None:
                return nmc.strip(), empty_state("No persisted proposal found", "The entered NMC does not appear in the registry visible to this environment."), []
            payload = {
                "nmc": row.nmc,
                "family": row.family,
                "status": row.status,
                "approval_status": row.approval_status,
                "attribute_signature": row.attribute_signature,
                "canonical_material_id": row.canonical_material_id,
            }
        return nmc.strip(), code_block(json.dumps(payload, indent=2, default=str)), [payload]
    except Exception as exc:  # pragma: no cover - runtime safeguard
        return nmc or "", error_state("NMC lookup could not be completed", "The registry layer returned an unexpected runtime error.", f"{type(exc).__name__}: {str(exc)[:180]}"), []


