@app.callback(
    Output("live-system-status", "children"),
    Input("live-refresh-interval", "n_intervals"),
    Input("live-refresh-button", "n_clicks"),
    prevent_initial_call=False,
)
def refresh_live_status(_intervals: int | None, _refresh_clicks: int | None):
    """Refresh cheap runtime signatures and the local API health indicator."""
    global _LAST_CORPUS_SIGNATURE, _LAST_QUALITY_SIGNATURE
    corpus_sig = _file_signature(CORPUS_PATH)
    quality_sig = _file_signature(QUALITY_PATH)
    with _LIVE_LOCK:
        corpus_changed = corpus_sig != _LAST_CORPUS_SIGNATURE
        _quality_changed = quality_sig != _LAST_QUALITY_SIGNATURE
        _LAST_CORPUS_SIGNATURE = corpus_sig
        _LAST_QUALITY_SIGNATURE = quality_sig
    if corpus_changed:
        search_index.cache_clear()
        corpus_stats.cache_clear()
    checked_at = datetime.now(timezone.utc).astimezone().strftime("%H:%M:%S")
    return live_status_component(checked_at=checked_at, force_refresh=True)


