@app.callback(
    Output("quality-csv-download", "data"),
    Input("quality-download", "n_clicks"),
    prevent_initial_call=True,
)
def download_quality_csv(_clicks: int | None):
    if ctx.triggered_id != "quality-download" or not _clicks or _clicks < 1:
        return None
    if not QUALITY_PATH.is_file():
        return csv_payload([], dataset_name="Data Quality Profile", metadata={"Name": "Quality Export", "Required information": "profile unavailable"}, filename="matrixen_quality_profile.csv")
    try:
        report = json.loads(QUALITY_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return csv_payload([], dataset_name="Data Quality Profile", metadata={"Name": "Quality Export", "Required information": str(exc)}, filename="matrixen_quality_profile.csv")
    rows = _quality_export_rows(report)
    return csv_payload(
        rows,
        dataset_name="Data Quality Profile",
        metadata={
            "Name": "Data Quality Export",
            "Required information": "source, encoding, records seen, retained, quarantined, errors, warnings, info",
            "Source": report.get("source_path", "unknown"),
            "Encoding": report.get("encoding", "unknown"),
            "Rows seen": report.get("records_seen", 0),
            "Rows retained": report.get("records_valid", 0),
            "Quarantined": report.get("records_quarantined", 0),
        },
        filename="matrixen_quality_profile.csv",
    )


@app.callback(
    Output("demo-state", "data"),
    Output("demo-timer", "n_intervals"),
    Output("demo-timer", "disabled"),
    Output("demo-elapsed", "children"),
    Output("demo-progress-fill", "style"),
    Output("demo-status", "children"),
    Output("demo-stage-strip", "children"),
    Output("demo-metrics", "children"),
    Output("demo-live-log", "children"),
    Output("demo-download", "disabled"),
    Input("demo-start", "n_clicks"),
    Input("demo-reset", "n_clicks"),
    Input("demo-timer", "n_intervals"),
    State("demo-state", "data"),
    prevent_initial_call=False,
)
def run_60_second_demo(_start_clicks: int | None, _reset_clicks: int | None, n_intervals: int | None, current: dict[str, Any] | None):
    state = dict(current or {"active": False, "completed": [], "active_stage": 0, "metrics": {}, "log": []})
    trigger = ctx.triggered_id
    if trigger == "demo-reset":
        reset = {"active": False, "completed": [], "active_stage": 0, "metrics": {}, "log": []}
        return reset, 0, True, "0:00", {"width": "0%"}, "Ready", _demo_stage_snapshot(reset), _demo_metrics(reset), empty_state("Ready for live execution", "Press Run 60-second demo to exercise the live pipeline."), True
    if trigger == "demo-start":
        # Use a deterministic current source description as the demonstration seed.
        seed_description = ""
        source_rows = 0
        if CORPUS_PATH.is_file():
            try:
                rows, _ = read_csv_records(CORPUS_PATH)
                source_rows = len(rows)
                for item in rows:
                    seed_description = (item.get("description") or "").strip()
                    if seed_description:
                        break
            except Exception as exc:  # pragma: no cover - runtime safeguard
                seed_description = ""
                source_rows = 0
                state["log"] = [f"Source read note: {str(exc)[:160]}"]
        started = {
            "active": True,
            "completed": [],
            "active_stage": 0,
            "seed_description": seed_description,
            "metrics": {"source_rows": source_rows},
            "log": ["Demo initiated: reading the current source environment."],
        }
        return started, 0, False, "0:00", {"width": "0%"}, "Initiating live demo…", _demo_stage_snapshot(started), _demo_metrics(started), html.Div([html.Div("DEMO INITIALIZING", className="demo-log-kicker"), html.P("Live source context detected. The next ticks execute the same project modules used by the workspace.", className="demo-log-copy")], className="demo-log-inner"), True
    if not state.get("active"):
        return state, int(n_intervals or 0), True, "0:00", {"width": "0%"}, "Ready", _demo_stage_snapshot(state), _demo_metrics(state), html.Div([html.Div("DEMO READY", className="demo-log-kicker"), html.P("No prerecorded result is stored here.", className="demo-log-copy")], className="demo-log-inner"), not bool(state.get("log"))

    tick = min(60, int(n_intervals or 0))
    stage = min(5, tick // 10)
    completed = set(state.get("completed", []))
    metrics = dict(state.get("metrics") or {})
    logs = list(state.get("log") or [])
    seed = str(state.get("seed_description") or "").strip()

    # Each stage executes exactly once per demo run. The first retrieval call benefits from
    # the background warm-up started below; subsequent calls reuse Matrixen's cached index.
    try:
        if 0 not in completed and stage >= 0:
            if not seed and CORPUS_PATH.is_file():
                rows, _ = read_csv_records(CORPUS_PATH)
                for item in rows:
                    seed = (item.get("description") or "").strip()
                    if seed:
                        break
            metrics["source_rows"] = metrics.get("source_rows", 0)
            completed.add(0)
            logs.append(f"01 Live fetch · source rows available: {metrics['source_rows']:,}.")
        if 1 not in completed and stage >= 1 and seed:
            attrs = extract_attributes(seed)
            normalized = NORMALIZER.normalize(seed)
            metrics["family"] = getattr(attrs, "family", "unknown") or "unknown"
            metrics["normalized_chars"] = len(getattr(normalized, "normalized_text", "") or "")
            completed.add(1)
            logs.append(f"02 Normalize · family={metrics['family']} · normalized text prepared.")
        if 2 not in completed and stage >= 2 and seed:
            engine, records = search_index()
            hits = engine.search(seed, limit=5)
            metrics["candidate_count"] = len(hits)
            metrics["top_candidate"] = str(hits[0]["candidate_id"]) if hits else "none"
            metrics["search_status"] = "completed"
            if hits:
                top_record = records.get(str(hits[0]["candidate_id"]))
                metrics["top_description"] = (top_record.raw_description[:140] if top_record else "")
            completed.add(2)
            logs.append(f"03 Hybrid search · {len(hits)} ranked candidate(s) returned.")
        if 3 not in completed and stage >= 3 and seed:
            engine, records = search_index()
            hits = engine.search(seed, limit=2)
            compare_text = seed
            if hits:
                candidate_hit = hits[1] if len(hits) > 1 else hits[0]
                top_record = records.get(str(candidate_hit["candidate_id"]))
                if top_record:
                    compare_text = top_record.raw_description
            decision, _features = PairScorer().score(seed, compare_text)
            metrics["pair_score"] = decision.score
            metrics["confidence_band"] = decision.confidence_band
            metrics["human_review"] = bool(decision.requires_human_review)
            completed.add(3)
            logs.append(f"04 Model score · score={decision.score} · band={decision.confidence_band} · review={decision.requires_human_review}.")
        if 4 not in completed and stage >= 4:
            queue = review_tasks()
            metrics["review_tasks"] = len(queue)
            DATABASE.initialize()
            nmc_count = 0
            try:
                with DATABASE.sessions() as session:
                    nmc_count = int(session.query(NMCRegistryRow).count())
            except Exception:
                nmc_count = 0
            metrics["nmc_registry_rows"] = nmc_count
            completed.add(4)
            logs.append(f"05 Governance · review queue={len(queue):,} · persisted registry rows={nmc_count:,}.")
        if 5 not in completed and stage >= 5:
            quality_signals = 0
            if QUALITY_PATH.is_file():
                report = json.loads(QUALITY_PATH.read_text(encoding="utf-8"))
                quality_signals = sum(_safe_count(v) for values in (report.get("error_counts", {}), report.get("warning_counts", {}), report.get("info_counts", {})) for v in (values or {}).values())
            metrics["quality_signals"] = quality_signals
            metrics["export_ready"] = True
            completed.add(5)
            logs.append(f"06 Quality + export · {quality_signals:,} quality signal count(s) flattened for CSV export.")
    except Exception as exc:  # pragma: no cover - demo safeguard
        logs.append(f"Demo runtime note · {type(exc).__name__}: {str(exc)[:180]}")

    previous_stage = int(state.get("active_stage", 0))
    previous_completed = tuple(state.get("completed", []))
    finished = tick >= 60
    state = {
        **state,
        "active": not finished,
        "active_stage": stage,
        "completed": sorted(completed),
        "metrics": metrics,
        "log": logs[-18:],
    }
    elapsed = "1:00" if finished else f"0:{tick:02d}"
    progress = {"width": "100%" if finished else f"{min(100, (tick / 60) * 100):.1f}%"}
    disabled = finished

    stage_changed = finished or stage != previous_stage or tuple(sorted(completed)) != previous_completed
    if stage_changed:
        status_text = "Demo complete · live pipeline executed" if finished else f"Stage {stage + 1} of 6 · working live"
        log_children = html.Div([
            html.Div("LIVE DEMO LOG", className="demo-log-kicker"),
            *[html.Div(entry, className="demo-log-entry") for entry in logs[-8:]],
        ], className="demo-log-inner")
        stage_children = _demo_stage_snapshot(state)
        metric_children = _demo_metrics(state)
    else:
        status_text = no_update
        log_children = no_update
        stage_children = no_update
        metric_children = no_update

    return state, tick, disabled, elapsed, progress, status_text, stage_children, metric_children, log_children, not bool(completed)


@app.callback(
    Output("demo-csv-download", "data"),
    Input("demo-download", "n_clicks"),
    State("demo-state", "data"),
    prevent_initial_call=True,
)
def download_demo_csv(_clicks: int | None, state: dict[str, Any] | None):
    # Demo navigation/timer state changes are never exports; only the explicit button can download.
    if ctx.triggered_id != "demo-download" or not _clicks or _clicks < 1:
        return None
    state = state or {}
    rows = [{"stage": idx + 1, "log_entry": entry} for idx, entry in enumerate(state.get("log") or [])]
    metrics = state.get("metrics") or {}
    return csv_payload(
        rows,
        dataset_name="60-second Live Demo Evidence Log",
        metadata={
            "Name": "Matrixen 60-second Demo",
            "Required information": "stage log + model/runtime metrics",
            **metrics,
        },
        filename="matrixen_60_second_demo_evidence.csv",
    )


